import sys
from collections import Counter

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    N, M = data[0], data[1]
    counts = sorted(Counter(data[2:2 + N]).items())

    def cost_up_to(x):
        total = 0
        for p, c in counts:
            if p > x:
                break
            k = (x // p + 1) // 2
            total += k * k * p * c
            if total > M:
                break
        return total

    low, high = 0, 2 * 10**18
    while high - low > 1:
        mid = (low + high) // 2
        if cost_up_to(mid) <= M:
            low = mid
        else:
            high = mid

    total_cost = 0
    total_items = 0
    for p, c in counts:
        if p > low:
            break
        k = (low // p + 1) // 2
        total_items += k * c
        total_cost += k * k * p * c

    total_items += (M - total_cost) // (low + 1)
    print(total_items)

if __name__ == "__main__":
    solve()
